class Solution {
public:
    int firstAtLeast(vector<int>& nums, int x) {
        int lo = 0, hi = nums.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (nums[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
    int maximumCount(vector<int>& nums) {
        int neg = firstAtLeast(nums, 0);
        int pos = nums.size() - firstAtLeast(nums, 1);
        return max(neg, pos);
    }
};
